/* ===== Design Tokens ===== */
:root {
  --clr-bg:           #0d0d0f;
  --clr-surface:      #16161a;
  --clr-surface-alt:  #1e1e24;
  --clr-border:       #2a2a34;
  --clr-border-light: #3a3a48;

  --clr-accent:       #e8b84b;
  --clr-accent-dim:   #c99a2e;
  --clr-accent-glow:  rgba(232, 184, 75, 0.18);
  --clr-red:          #e84b4b;
  --clr-red-dim:      #c92e2e;
  --clr-green:        #4be87a;

  --clr-text:         #f0eff4;
  --clr-text-muted:   #9998a8;
  --clr-text-subtle:  #6e6d7e;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);

  --transition: 200ms ease;
  --transition-slow: 350ms ease;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.6rem 1.2rem;
  background: var(--clr-accent);
  color: #000;
  font-weight: 700;
  border-radius: var(--radius-sm);
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: 1.5rem;
}

/* ===== Header / Nav ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--clr-text);
  flex-shrink: 0;
}

.nav-logo svg { color: var(--clr-accent); }

.nav-links {
  display: flex;
  gap: 0.25rem;
  flex: 1;
}

.nav-links a {
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a[aria-current="page"] {
  color: var(--clr-text);
  background: var(--clr-surface-alt);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: auto;
}

.nav-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.nav-btn:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 16px;
  height: 16px;
  padding-inline: 4px;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 99px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.55rem 1.25rem;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-primary:hover {
  background: #f0c75a;
  box-shadow: 0 0 20px var(--clr-accent-glow);
  transform: translateY(-1px);
}
.btn-primary:active { transform: translateY(0); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.25rem;
  border: 1px solid var(--clr-border-light);
  color: var(--clr-text);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}
.btn-ghost:hover { border-color: var(--clr-text-muted); background: var(--clr-surface-alt); }

.mobile-menu-btn {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.mobile-menu-btn:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

/* ===== Hero ===== */
.hero {
  position: relative;
  overflow: hidden;
  padding-block: 5rem 4rem;
  background: linear-gradient(135deg, #0d0d0f 0%, #14101e 50%, #0d0d0f 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 60% at 70% 50%, rgba(232,184,75,0.06) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(100,60,200,0.07) 0%, transparent 60%);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.75rem;
  background: var(--clr-accent-glow);
  border: 1px solid rgba(232,184,75,0.3);
  border-radius: 99px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin-bottom: 1.25rem;
}

.hero-title .accent { color: var(--clr-accent); }

.hero-desc {
  font-size: 1.05rem;
  color: var(--clr-text-muted);
  max-width: 44ch;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--clr-border);
}
.stat-num {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--clr-text);
  letter-spacing: -0.02em;
}
.stat-label {
  font-size: 0.8rem;
  color: var(--clr-text-muted);
  margin-top: 0.15rem;
}

.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.hero-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow);
}
.hero-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }
.hero-card:first-child { grid-row: span 2; }

.hero-card-img {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.hero-card:first-child .hero-card-img { aspect-ratio: 3/4; font-size: 6rem; }

.hero-card-body {
  padding: 0.85rem 1rem;
  border-top: 1px solid var(--clr-border);
}
.hero-card-name { font-size: 0.82rem; font-weight: 600; }
.hero-card-price { font-size: 0.95rem; font-weight: 800; color: var(--clr-accent); margin-top: 0.1rem; }

/* ===== Section Shared ===== */
section { padding-block: 4rem; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.25rem;
  flex-wrap: wrap;
}
.section-label {
  display: block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 0.35rem;
}
.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.section-view-all {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--clr-text-muted);
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  transition: color var(--transition);
  flex-shrink: 0;
}
.section-view-all:hover { color: var(--clr-accent); }

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow), border-color var(--transition);
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: var(--clr-border-light);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--clr-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  overflow: hidden;
}

.product-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.2rem 0.55rem;
  border-radius: 99px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.product-badge--new { background: var(--clr-green); color: #000; }
.product-badge--sale { background: var(--clr-red); color: #fff; }
.product-badge--hot { background: var(--clr-accent); color: #000; }

.product-wishlist {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  width: 32px;
  height: 32px;
  background: rgba(13,13,15,0.7);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { color: var(--clr-red); background: rgba(232,75,75,0.15); }
.product-wishlist[aria-pressed="true"] svg { fill: var(--clr-red); }

.product-body {
  padding: 1rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.product-category {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--clr-text-subtle);
  margin-bottom: 0.25rem;
}
.product-name {
  font-size: 0.92rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 0.5rem;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin-bottom: 0.75rem;
}
.stars { color: var(--clr-accent); font-size: 0.75rem; letter-spacing: 0.05em; }
.rating-count { font-size: 0.72rem; color: var(--clr-text-subtle); }

.product-pricing {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 0.85rem;
  margin-top: auto;
}
.price-current { font-size: 1.1rem; font-weight: 800; color: var(--clr-text); }
.price-original { font-size: 0.85rem; color: var(--clr-text-subtle); text-decoration: line-through; }
.price-save { font-size: 0.72rem; font-weight: 700; color: var(--clr-green); }

.product-add-btn {
  width: 100%;
  padding: 0.6rem;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  color: var(--clr-text);
  font-size: 0.85rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}
.product-add-btn:hover {
  background: var(--clr-accent);
  border-color: var(--clr-accent);
  color: #000;
}
.product-add-btn.added {
  background: rgba(75,232,122,0.12);
  border-color: var(--clr-green);
  color: var(--clr-green);
}

/* ===== Deals Section ===== */
.deals-section { background: var(--clr-surface); border-block: 1px solid var(--clr-border); }

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow), border-color var(--transition);
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
  border-color: var(--clr-border-light);
}

.deal-card--featured {
  background: linear-gradient(135deg, #1a1208 0%, #16100a 100%);
  border-color: rgba(232,184,75,0.3);
}

.deal-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 0.5rem; }
.deal-emoji { font-size: 2.5rem; line-height: 1; }

.deal-discount-badge {
  padding: 0.25rem 0.65rem;
  background: var(--clr-red);
  color: #fff;
  font-size: 0.8rem;
  font-weight: 800;
  border-radius: 99px;
}
.deal-card--featured .deal-discount-badge { background: var(--clr-accent); color: #000; }

.deal-name { font-size: 1rem; font-weight: 700; line-height: 1.3; }
.deal-desc { font-size: 0.83rem; color: var(--clr-text-muted); line-height: 1.55; }

.deal-pricing { display: flex; align-items: baseline; gap: 0.6rem; }
.deal-price-current { font-size: 1.4rem; font-weight: 800; }
.deal-card--featured .deal-price-current { color: var(--clr-accent); }
.deal-price-original { font-size: 0.9rem; color: var(--clr-text-subtle); text-decoration: line-through; }

.deal-progress { display: flex; flex-direction: column; gap: 0.4rem; }
.deal-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
  color: var(--clr-text-subtle);
}
.progress-bar {
  height: 5px;
  background: var(--clr-border);
  border-radius: 99px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: var(--clr-red);
  border-radius: 99px;
  transition: width 1s ease;
}
.deal-card--featured .progress-fill { background: var(--clr-accent); }

.deal-timer {
  display: flex;
  gap: 0.4rem;
  align-items: center;
}
.timer-segment {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  padding: 0.35rem 0.55rem;
  min-width: 44px;
}
.timer-num { font-size: 1rem; font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }
.timer-label { font-size: 0.6rem; color: var(--clr-text-subtle); text-transform: uppercase; letter-spacing: 0.05em; margin-top: 2px; }
.timer-sep { font-size: 1rem; font-weight: 700; color: var(--clr-text-subtle); align-self: flex-start; margin-top: 6px; }

/* ===== Editorial ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

.editorial-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow), border-color var(--transition);
}
.editorial-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-hover);
  border-color: var(--clr-border-light);
}

.editorial-card--hero {
  grid-column: span 2;
  grid-row: span 2;
}

.editorial-img {
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  background: var(--clr-surface-alt);
  position: relative;
  overflow: hidden;
}
.editorial-card--hero .editorial-img { aspect-ratio: 4/3; font-size: 7rem; }

.editorial-img-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(13,13,15,0.7) 0%, transparent 60%);
}

.editorial-tag {
  position: absolute;
  bottom: 0.85rem;
  left: 0.85rem;
  padding: 0.2rem 0.6rem;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.7rem;
  font-weight: 700;
  border-radius: 99px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.editorial-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; }
.editorial-meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.73rem;
  color: var(--clr-text-subtle);
  margin-bottom: 0.6rem;
}
.editorial-meta-dot { width: 3px; height: 3px; background: var(--clr-border-light); border-radius: 50%; }

.editorial-title {
  font-size: 0.95rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 0.5rem;
}
.editorial-card--hero .editorial-title { font-size: 1.2rem; }
.editorial-title a { transition: color var(--transition); }
.editorial-title a:hover { color: var(--clr-accent); }

.editorial-excerpt {
  font-size: 0.83rem;
  color: var(--clr-text-muted);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-read-more {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--clr-accent);
  margin-top: 0.9rem;
  transition: gap var(--transition);
}
.editorial-read-more:hover { gap: 0.5rem; }

/* ===== Banner Strip ===== */
.banner-strip {
  background: var(--clr-accent);
  color: #000;
  padding-block: 0.6rem;
  overflow: hidden;
}
.banner-track {
  display: flex;
  gap: 3rem;
  white-space: nowrap;
  animation: marquee 28s linear infinite;
}
.banner-track:hover { animation-play-state: paused; }
.banner-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
  font-weight: 700;
}
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ===== Newsletter ===== */
.newsletter-section {
  background: linear-gradient(135deg, #14101e 0%, #0d0d0f 100%);
  border-top: 1px solid var(--clr-border);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.newsletter-title {
  font-size: clamp(1.4rem, 2.5vw, 1.8rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}
.newsletter-desc { font-size: 0.9rem; color: var(--clr-text-muted); line-height: 1.65; }

.newsletter-form { display: flex; flex-direction: column; gap: 0.75rem; }
.form-row { display: flex; gap: 0.6rem; }

.newsletter-input {
  flex: 1;
  padding: 0.7rem 1rem;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  color: var(--clr-text);
  font-size: 0.9rem;
  font-family: inherit;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: var(--clr-text-subtle); }
.newsletter-input:focus { outline: 2px solid var(--clr-accent); outline-offset: 0; border-color: transparent; }

.newsletter-privacy {
  font-size: 0.75rem;
  color: var(--clr-text-subtle);
  line-height: 1.5;
}
.newsletter-privacy a { color: var(--clr-text-muted); text-decoration: underline; }
.newsletter-privacy a:hover { color: var(--clr-accent); }

.newsletter-success {
  display: none;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  background: rgba(75,232,122,0.1);
  border: 1px solid rgba(75,232,122,0.3);
  border-radius: var(--radius-sm);
  color: var(--clr-green);
  font-size: 0.875rem;
  font-weight: 600;
}
.newsletter-success.visible { display: flex; }

/* ===== Footer ===== */
.site-footer {
  background: var(--clr-surface);
  border-top: 1px solid var(--clr-border);
  padding-block: 3rem 1.5rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
  margin-bottom: 2.5rem;
}
.footer-brand p {
  font-size: 0.85rem;
  color: var(--clr-text-muted);
  line-height: 1.65;
  margin-block: 0.75rem 1.25rem;
  max-width: 30ch;
}
.footer-social { display: flex; gap: 0.5rem; }
.footer-social a {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.footer-social a:hover { color: var(--clr-accent); border-color: var(--clr-accent); background: var(--clr-accent-glow); }

.footer-col h3 { font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--clr-text); margin-bottom: 1rem; }
.footer-col ul { display: flex; flex-direction: column; gap: 0.5rem; }
.footer-col ul a { font-size: 0.85rem; color: var(--clr-text-muted); transition: color var(--transition); }
.footer-col ul a:hover { color: var(--clr-text); }

.footer-bottom {
  border-top: 1px solid var(--clr-border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: 0.8rem;
  color: var(--clr-text-subtle);
}
.footer-payments { display: flex; gap: 0.4rem; }
.payment-icon {
  padding: 0.25rem 0.5rem;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--clr-text-muted);
}

/* ===== Cart Drawer ===== */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(4px);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(420px, 100vw);
  background: var(--clr-surface);
  border-left: 1px solid var(--clr-border);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}
.cart-drawer.open { transform: translateX(0); }

.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--clr-border);
}
.cart-header h2 { font-size: 1.1rem; font-weight: 700; }
.cart-close {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.cart-close:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

.cart-items { flex: 1; overflow-y: auto; padding: 1rem 1.5rem; display: flex; flex-direction: column; gap: 1rem; }
.cart-empty { text-align: center; padding: 3rem 1rem; color: var(--clr-text-muted); }
.cart-empty-icon { font-size: 3rem; margin-bottom: 1rem; }
.cart-empty p { font-size: 0.9rem; }

.cart-item {
  display: flex;
  gap: 1rem;
  padding: 0.85rem;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
}
.cart-item-img {
  width: 60px; height: 60px;
  background: var(--clr-bg);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.75rem;
  flex-shrink: 0;
}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name { font-size: 0.85rem; font-weight: 600; line-height: 1.3; }
.cart-item-price { font-size: 0.9rem; font-weight: 700; color: var(--clr-accent); margin-top: 0.25rem; }
.cart-item-qty {
  display: flex; align-items: center; gap: 0.5rem;
  margin-top: 0.5rem;
}
.qty-btn {
  width: 24px; height: 24px;
  display: flex; align-items: center; justify-content: center;
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: 4px;
  color: var(--clr-text);
  font-size: 1rem;
  transition: background var(--transition), border-color var(--transition);
}
.qty-btn:hover { background: var(--clr-surface); border-color: var(--clr-border-light); }
.qty-value { font-size: 0.85rem; font-weight: 600; min-width: 20px; text-align: center; }

.cart-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--clr-border);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.cart-subtotal {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  color: var(--clr-text-muted);
}
.cart-total {
  display: flex;
  justify-content: space-between;
  font-size: 1.05rem;
  font-weight: 700;
}
.cart-checkout-btn {
  width: 100%;
  padding: 0.8rem;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.95rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition), box-shadow var(--transition);
}
.cart-checkout-btn:hover { background: #f0c75a; box-shadow: 0 0 20px var(--clr-accent-glow); }

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border-width: 0;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 1.5rem; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--hero { grid-column: span 2; grid-row: span 1; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 700px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: flex; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--hero { grid-column: span 1; }
  .footer-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .products-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
}

@media (max-width: 480px) {
  .hero { padding-block: 3rem 2.5rem; }
  .hero-stats { gap: 1.25rem; }
  .form-row { flex-direction: column; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ===== Mobile Nav Drawer ===== */
.mobile-nav {
  position: fixed;
  inset: 0;
  z-index: 150;
  pointer-events: none;
}
.mobile-nav-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.6);
  opacity: 0;
  transition: opacity var(--transition-slow);
}
.mobile-nav-panel {
  position: absolute;
  top: 0; left: 0; bottom: 0;
  width: min(300px, 80vw);
  background: var(--clr-surface);
  border-right: 1px solid var(--clr-border);
  padding: 1.5rem;
  transform: translateX(-100%);
  transition: transform var(--transition-slow);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.mobile-nav.open { pointer-events: all; }
.mobile-nav.open .mobile-nav-overlay { opacity: 1; }
.mobile-nav.open .mobile-nav-panel { transform: translateX(0); }
.mobile-nav-close {
  align-self: flex-end;
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  margin-bottom: 0.5rem;
  transition: color var(--transition), background var(--transition);
}
.mobile-nav-close:hover { color: var(--clr-text); background: var(--clr-surface-alt); }
.mobile-nav-panel a {
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.mobile-nav-panel a:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

/* ===== Animations / Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
  .banner-track { animation: none; }
}

