+
+.deal-name { font-size: 1rem; font-weight: 700; line-height: 1.3; }
+.deal-desc { font-size: 0.83rem; color: var(--clr-text-muted); line-height: 1.55; }
+
+.deal-pricing { display: flex; align-items: baseline; gap: 0.6rem; }
