:root {
  --clr-bg:           #0d0d0f;
  --clr-surface:      #16161a;
  --clr-surface-alt:  #1e1e24;
  --clr-border:       #2a2a34;
  --clr-border-light: #3a3a48;

  --clr-accent:       #e8b84b;
  --clr-accent-dim:   #c99a2e;
  --clr-accent-glow:  rgba(232, 184, 75, 0.18);
  --clr-red:          #e84b4b;
  --clr-red-dim:      #c92e2e;
  --clr-green:        #4be87a;

  --clr-text:         #f0eff4;
  --clr-text-muted:   #9998a8;
  --clr-text-subtle:  #6e6d7e;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);

  --transition: 200ms ease;
  --transition-slow: 350ms ease;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.6rem 1.2rem;
  background: var(--clr-accent);
  color: #000;
  font-weight: 700;
  border-radius: var(--radius-sm);
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: 1.5rem;
}

/* ===== Header / Nav ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--clr-text);
  flex-shrink: 0;
}

.nav-logo svg { color: var(--clr-accent); }

.nav-links {
  display: flex;
  gap: 0.25rem;
  flex: 1;
}

.nav-links a {
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.nav-links a:hover,
.nav-links a[aria-current="page"] {
  color: var(--clr-text);
  background: var(--clr-surface-alt);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: auto;
}

.nav-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.nav-btn:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 16px;
  height: 16px;
  padding-inline: 4px;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.65rem;
  font-weight: 700;
  border-radius: 99px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.55rem 1.25rem;
  background: var(--clr-accent);
  color: #000;
  font-size: 0.875rem;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-primary:hover {
  background: #f0c75a;
  box-shadow: 0 0 20px var(--clr-accent-glow);
  transform: translateY(-1px);
}
.btn-primary:active { transform: translateY(0); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.25rem;
  border: 1px solid var(--clr-border-light);
  color: var(--clr-text);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}
.btn-ghost:hover { border-color: var(--clr-text-muted); background: var(--clr-surface-alt); }

.mobile-menu-btn {
  display: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
}
.mobile-menu-btn:hover { color: var(--clr-text); background: var(--clr-surface-alt); }

/* ===== Hero ===== */
.hero {
  position: relative;
  overflow: hidden;
  padding-block: 5rem 4rem;
  background: linear-gradient(135deg, #0d0d0f 0%, #14101e 50%, #0d0d0f 100%);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 60% at 70% 50%, rgba(232,184,75,0.06) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 20% 80%, rgba(100,60,200,0.07) 0%, transparent 60%);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.75rem;
  background: var(--clr-accent-glow);
  border: 1px solid rgba(232,184,75,0.3);
  border-radius: 99px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin-bottom: 1.25rem;
}

.hero-title .accent { color: var(--clr-accent); }

.hero-desc {
  font-size: 1.05rem;
  color: var(--clr-text-muted);
  max-width: 44ch;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--clr-border);
}
.stat-num {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--clr-text);
  letter-spacing: -0.02em;
}
.stat-label {
  font-size: 0.8rem;
  color: var(--clr-text-muted);
  margin-top: 0.15rem;
}

.hero-visual {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.hero-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow);
}
.hero-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-hover); }
.hero-card:first-child { grid-row: span 2; }

.hero-card-img {
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}
.hero-card:first-child .hero-card-img { aspect-ratio: 3/4; font-size: 6rem; }

.hero-card-body {
  padding: 0.85rem 1rem;
  border-top: 1px solid var(--clr-border);
}
.hero-card-name { font-size: 0.82rem; font-weight: 600; }
.hero-card-price { font-size: 0.95rem; font-weight: 800; color: var(--clr-accent); margin-top: 0.1rem; }

/* ===== Section Shared ===== */
section { padding-block: 4rem; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.25rem;
  flex-wrap: wrap;
}
.section-label {
  display: block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 0.35rem;
}
.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.section-view-all {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--clr-text-muted);
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  transition: color var(--transition);
  flex-shrink: 0;
}
.section-view-all:hover { color: var(--clr-accent); }

/* ===== Product Cards ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-slow), box-shadow var(--transition-slow), border-color var(--transition);
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
  border-color: var(--clr-border-light);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--clr-surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  overflow: hidden;
}

.product-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.2rem 0.55rem;
  border-radius: 99px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}
.product-badge--new { background: var(--clr-green); color: #000; }
.product-badge--sale { background: var(--clr-red); color: #fff; }
.product-badge--hot { background: var(--clr-accent); color: #000; }

.product-wishlist {
  position: absolute;
  top: 0.6rem;
