:root {
  --clr-bg:           #0d0d0f;
  --clr-surface:      #16161a;
  --clr-surface-alt:  #1e1e24;
  --clr-border:       #2a2a34;
  --clr-border-light: #3a3a48;

  --clr-accent:       #e8b84b;
  --clr-accent-dim:   #c99a2e;
  --clr-accent-glow:  rgba(232, 184, 75, 0.18);
  --clr-red:          #e84b4b;
  --clr-red-dim:      #c92e2e;
  --clr-green:        #4be87a;

  --clr-text:         #f0eff4;
  --clr-text-muted:   #9998a8;
  --clr-text-subtle:  #6e6d7e;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;

  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-hover: 0 8px 40px rgba(0,0,0,0.6);

  --transition: 200ms ease;
  --transition-slow: 350ms ease;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Inter', system-ui, -apple-system, sans-serif;
}

/* ===== Reset ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
:focus-visible {
  outline: 2px solid var(--clr-accent);
  outline-offset: 3px;
  border-radius: 3px;
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.6rem 1.2rem;
  background: var(--clr-accent);
  color: #000;
  font-weight: 700;
  border-radius: var(--radius-sm);
  z-index: 1000;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: 1.5rem;
}

/* ===== Header / Nav ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
}

.nav-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--clr-text);
  flex-shrink: 0;
}

.nav-logo svg { color: var(--clr-accent); }

.nav-links {
  display: flex;
  gap: 0.25rem;
