  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.footer-social a:hover { color: var(--clr-accent); border-color: var(--clr-accent); background: var(--clr-accent-glow); }

.footer-col h3 { font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--clr-text); margin-bottom: 1rem; }
.footer-col ul { display: flex; flex-direction: column; gap: 0.5rem; }
.footer-col ul a { font-size: 0.85rem; color: var(--clr-text-muted); transition: color var(--transition); }
.footer-col ul a:hover { color: var(--clr-text); }

.footer-bottom {
  border-top: 1px solid var(--clr-border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  font-size: 0.8rem;
  color: var(--clr-text-subtle);
}
.footer-payments { display: flex; gap: 0.4rem; }
.payment-icon {
  padding: 0.25rem 0.5rem;
  background: var(--clr-surface-alt);
  border: 1px solid var(--clr-border);
  border-radius: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--clr-text-muted);
}

/* ===== Cart Drawer ===== */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  backdrop-filter: blur(4px);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-slow);
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(420px, 100vw);
  background: var(--clr-surface);
  border-left: 1px solid var(--clr-border);
  z-index: 201;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform var(--transition-slow);
}
.cart-drawer.open { transform: translateX(0); }

.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--clr-border);
}
.cart-header h2 { font-size: 1.1rem; font-weight: 700; }
.cart-close {
  width: 36px; height: 36px;
  display: flex; align-items: center; justify-content: center;
